const items = $input.all();
const raw = (items[0]?.json?.data) || [];
const pageId = '1274733055725344';
const out = [];

for (const c of raw) {
  const cust = (c.participants?.data || []).find(p => p.id !== pageId);
  const custId = cust?.id ?? 'Chưa rõ';
  const custName = cust?.name ?? 'Khách Facebook';
  out.push({
    fb_conversation_id: c.id,
    customer_id: custId,
    customer_name: custName,
    fb_message_count: Number(c.message_count ?? 0),
    fb_updated_time: c.updated_time,
    conversation_link: `https://business.facebook.com/latest/inbox/all?asset_id=${pageId}&selected_item_id=${custId}`
  });
}

return out.length > 0 ? out.map(x => ({ json: x })) : [{ json: { empty: true } }];

const fb = $('2. Bóc tách từng hội thoại').item.json;
const dbRow = $json;

const fbCount = fb.fb_message_count ?? 0;
const dbCount = dbRow.db_message_count ?? 0;
const diff = Math.max(0, fbCount - dbCount);

return {
  json: {
    ...fb,
    db_conversation_id: dbRow.db_conversation_id ?? null,
    db_message_count: dbCount,
    diff_count: diff,
    needs_sync: diff > 0 || !dbRow.db_conversation_id
  }
};

const pageId = '1274733055725344';
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const rawMsgs = item.json.data ?? [];
  let convId = null;
  try {
    const convDb = $('5. Đảm bảo Conversation tồn tại trong DB').itemMatching(i).json;
    convId = convDb.conversation_id;
  } catch (e) {
    try {
      convId = $('5. Đảm bảo Conversation tồn tại trong DB').all()[i]?.json?.conversation_id;
    } catch (e2) {}
  }

  for (const m of rawMsgs) {
    // Chặn rác: Bỏ qua tin nhắn không có text và không có attachments
    const msgText = (m.message || '').trim();
    const hasAttachments = Boolean(m.attachments?.data?.length);
    if (!msgText && !hasAttachments) continue;

    const isFromPage = m.from?.id === pageId;
    out.push({
      conversation_id: convId,
      external_message_id: m.id,
      sender_type: isFromPage ? 'ASSISTANT' : 'USER',
      role: isFromPage ? 'assistant' : 'user',
      content: msgText || '[Đính kèm file/hình ảnh]',
      created_at: m.created_time,
      attachments: JSON.stringify(m.attachments?.data || [])
    });
  }
}

return out.length > 0 ? out.map(x => ({ json: x })) : [{ json: { empty: true } }];

const convItems = $('4. So sánh trạng thái đồng bộ').all();
const out = [];

for (const it of convItems) {
  const d = it.json;
  const isSynced = (d.db_message_count + d.diff_count) >= d.fb_message_count;

  out.push({
    "Khách hàng": d.customer_name,
    "Facebook ID (PSID)": d.customer_id,
    "Số tin nhắn trên Page": d.fb_message_count,
    "Số tin nhắn trong Database": d.db_message_count + d.diff_count,
    "Trạng thái đồng bộ": isSynced ? "✅ ĐÃ KHỚP 100% (ĐÃ ĐỒNG BỘ)" : "⏳ ĐANG CẬP NHẬT",
    "Thời gian tin nhắn cuối": d.fb_updated_time,
    "Link xem hội thoại trên Facebook": d.conversation_link,
    "Thời gian kiểm tra": new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
  });
}

return out.map(x => ({ json: x }));
